{"content": [{"type": "text", "text": "{"status":"success","path":"outline.json","content":"{\n  \"outline\": {\n    \"act_one\": {\n      \"story_synopsis\": \"林深在姐姐忌日发现家族企业秘密账本，揭开三年前姐姐被迫害真相——亲叔叔林震为掩盖贪污伪造姐姐自杀现场。此时他与新入职的律师陈墨因案件产生交集，陈墨暗中调查同一案件却因家族压力受阻。林深试图通过黑客苏婉破解家族系统获取证据，却发现苏婉因赌债被林震控制。第一幕在林深潜入家族档案室被林震撞见时达到转折：林震当面烧毁账本，警告林深'有些真相永远不该被揭开'。\",\n      \"chapter_synopsis\": [\n        {\n          \"chapter_number\": 1,\n          \"synopsis\": \"林深在姐姐忌日潜入墓园，发现陈墨在调查同一案件（起始：林深孤独复仇，陈墨暗中观察）。林深跟踪陈墨至咖啡馆，听到陈墨与神秘人通话提及'账本'（推进：发现共同目标）。林深主动接触陈墨，两人达成临时同盟（结束：从敌对到互相利用的危险平衡）。\"\n        },\n        {\n          \"chapter_number\": 2,\n          \"synopsis\": \"苏婉在地下赌场被林震手下追债，林深出手相助但要求破解家族系统（起始：苏婉绝望，林深提出交易）。苏婉破解系统时发现姐姐死亡真相的加密文件（推进：关键证据浮现）。林震突然造访苏婉住所，威胁若不交出破解成果就曝光她妹妹的下落（结束：苏婉被迫妥协，林深计划受阻）。\"\n        },\n        {\n          \"chapter_number\": 3,\n          \"synopsis\": \"林深与陈墨策划潜入档案室，陈墨利用律师身份制造混乱（起始：精密计划启动）。林深在档案室找到账本却被林震围堵（冲突爆发：正面对峙）。林震烧毁账本并警告林深，陈墨暗中用手机录下全程（结束：证据被毁但留下录音，关系从利用转向信任）。\"\n        }\n      ],\n      \"scene_sequence\": [\n        {\n          \"scene_number\": 1,\n          \"scene_location\": \"墓园偏僻角落，黄昏细雨\",\n          \"characters_present\": [\"林深\", \"陈墨\"],\n          \"scene_purpose\": \"建立两人初始关系，埋下共同目标伏笔\",\n          \"core_action\": \"林深将白菊放在姐姐墓前，陈墨从树后走出递上同一品牌香烟\",\n          \"conflict_point\": \"陈墨指出林深复仇方式会伤害无辜，两人发生言语冲突\",\n          \"emotional_shift\": \"从'独自承受'的孤独 → '被理解'的震惊\",\n          \"scene_outcome\": \"陈墨留下联系方式，林深发现陈墨知道姐姐死亡真相\"\n        },\n        {\n          \"scene_number\": 2,\n          \"scene_location\": \"地下赌场后巷，霓虹灯闪烁\",\n          \"characters_present\": [\"苏婉\", \"林深\", \"追债者\"],\n          \"scene_purpose\": \"展示苏婉困境，建立与林深的交易关系\",\n          \"core_action\": \"苏婉被追债者按在墙上，林深用防狼喷雾制服对方\",\n          \"conflict_point\": \"苏婉拒绝合作，林深揭示知道她妹妹下落\",\n          \"emotional_shift\": \"从'绝望'的麻木 → '被威胁'的愤怒\",\n          \"scene_outcome\": \"苏婉同意合作但要求先见妹妹\"\n        },\n        {\n          \"scene_number\": 3,\n          \"scene_location\": \"家族企业档案室，深夜应急